import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Benchmarking","description":"QuickJS and the Static Hermes profile, collector and parser matrix","frontmatter":{"title":"Benchmarking","description":"QuickJS and the Static Hermes profile, collector and parser matrix","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/benchmarking.md"},"headers":[],"relativePath":"guides/benchmarking.md","filePath":"docs/benchmarking.md","lastUpdated":1792252051000}`),a={name:`guides/benchmarking.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="compare-quickjs-and-static-hermes" tabindex="-1">Compare QuickJS and Static Hermes <a class="header-anchor" href="#compare-quickjs-and-static-hermes" aria-label="Permalink to “Compare QuickJS and Static Hermes”">​</a></h1><p>This guide shows you how to run the repository&#39;s engine comparison and how much to read into its results. It builds nine production WebAssembly components—a QuickJS baseline and eight Static Hermes configurations—and runs the same workloads on Pumpkin. The results help compare these builds on this workload suite; they can&#39;t predict which engine will be faster for every plugin.</p><h2 id="run-the-comparison" tabindex="-1">Run the comparison <a class="header-anchor" href="#run-the-comparison" aria-label="Permalink to “Run the comparison”">​</a></h2><p>From the repository root, run:</p><pre><code>pnpm --filter @pumpkin-plugins/engine-comparison compare-engines
</code></pre><p>The command first runs the cacheable <code>benchmark:build</code> Turbo task, then runs the real-server integration test in <a href="../benchmarks/engine-comparison/test/engine-comparison.test.ts">engine-comparison.test.ts</a>. Turbo caches the nine comparison components and two stack-guard fixtures under configuration-specific paths in <code>build/engine-comparison/</code>. It can reuse them when the benchmark sources, build dependencies, and declared build environment match. The test starts a fresh Pumpkin server for each comparison component, runs the benchmark command, collects its results, and stops the server.</p><p>CI runs the nine engine configurations as parallel matrix jobs, along with both stack-guard checks. Each engine job uploads its result. The report job checks that all configurations ran the same workloads and produced matching checksums, then adds the combined Markdown report to the job summary. It uploads the combined JSON results and report for 90 days; individual engine result artifacts are kept for one day. Static Hermes preparation runs automatically when a local build needs it. In CI, the pinned toolchain is restored and verified before the comparison runs in the <a href="../.github/workflows/engine-comparison.yml">engine comparison workflow</a>.</p><p>After a pull-request CI run produces a complete report, a separate trusted workflow updates one benchmark comment on the PR, even if another CI job failed. It compares the results with the newest successful default-branch benchmark that is an ancestor of the PR base. By default, changes within 10% count as runner jitter; set the repository variable <code>BENCHMARK_JITTER_PERCENT</code> to change that threshold. A slower result beyond the threshold gets a warning. A significant improvement gets a celebration if there are no regressions; otherwise, the comment reports the run without a performance alert. The comment links to the full matrix report, embeds an SVG chart of the largest changes, and links to the chart for download. If no matching baseline artifact exists, it says so and leaves timing changes unclassified.</p><p>The benchmark plugin and workload definitions live in <a href="../benchmarks/engine-comparison/src/benchmark-plugin.ts">benchmark-plugin.ts</a> and <a href="../benchmarks/engine-comparison/src/benchmark-workloads.ts">benchmark-workloads.ts</a>.</p><h2 id="what-the-comparison-runs" tabindex="-1">What the comparison runs <a class="header-anchor" href="#what-the-comparison-runs" aria-label="Permalink to “What the comparison runs”">​</a></h2><p>Each configuration uses the same benchmark plugin source and workloads:</p><ul><li><strong>QuickJS</strong> bundles the JavaScript as an ES module and turns it into a component with this repository&#39;s QuickJS runtime.</li><li><strong>Static Hermes</strong> covers all combinations of the <code>full</code> and <code>lean</code> runtime profiles, Hades and malloc collectors, and JavaScript and TypeScript parser modes.</li><li><strong>Full</strong> keeps runtime source compilation available. <strong>Lean</strong> omits it, so <code>eval</code> and the <code>Function</code> constructor are unavailable.</li><li><strong>JavaScript parser mode</strong> uses Hermes&#39;s default parser. <strong>TypeScript parser mode</strong> enables Hermes&#39;s <code>--parse-ts</code> flag.</li></ul><p>The parser setting changes a compiler flag, not the benchmark code or inputs. The matrix has one QuickJS build and eight Static Hermes builds.</p><p>Here, “Static Hermes” means Hermes is linked into the WASI component. The plugin&#39;s JavaScript is compiled to Hermes bytecode before the component runs; it is not translated into native Wasm instructions. JIT is disabled in this WASI build. Pumpkin runs every configuration as a Wasm component, not as a native desktop engine binary.</p><p>Production builds minify the bundle. For plugins built inside this repository, the build tool enforces a 5 MiB component limit (5,242,880 bytes). External consumers get a warning and can continue. See the <a href="./../tools/static-hermes-runtime/README">Static Hermes Runtime guide</a> and <a href="/pumpkin-plugins/guides/building">build guide</a> for build flags, pinned tools, and runtime details.</p><h2 id="method-and-scope" tabindex="-1">Method and scope <a class="header-anchor" href="#method-and-scope" aria-label="Permalink to “Method and scope”">​</a></h2><p>Every configuration gets the same workload source and input count. The integration test compares deterministic checksums across all nine configurations and pins expected checksums for selected string and command fixtures. It also checks that:</p><ul><li>every engine reports the same workload identifiers, input counts, and checksums;</li><li>each timed workload has one un-timed warm-up followed by five measured samples;</li><li>the production component is non-empty and within the build-size limit;</li><li>the plugin registers its command and exercises selected real Pumpkin API behavior.</li></ul><p>The benchmark uses JavaScript <code>Date.now()</code>, so timings are whole milliseconds and the clock may have coarser resolution. For each workload, the report shows the median of five samples and their minimum-to-maximum range. Timing covers the workload body only; it excludes component compilation, server startup, plugin loading, and dispatch of the outer benchmark command.</p><p>There are 34 timed workloads: 33 deterministic guest-side fixtures and 1 real Pumpkin API call.</p><p>These fixture algorithms are examples written for this benchmark. They don&#39;t run the named plugins or Pumpkin&#39;s own command router. Player-oriented fixtures use in-memory test data rather than connected players.</p><p>Locally, the test runs configurations one at a time in a fixed order: QuickJS first, then each Static Hermes profile, collector, and parser-mode combination. It starts a fresh server for each one. CI runs the configurations in parallel. The real API workload calls <code>server.getAllPlayers()</code> in every sample; because the test server has no connected players, each call returns an empty list. Separately, the test registers and dispatches a real <code>server.command()</code> command and checks event and scheduled-task behavior. That command dispatch checks API behavior; it is not a timed command-routing workload.</p><h3 id="workload-inventory" tabindex="-1">Workload inventory <a class="header-anchor" href="#workload-inventory" aria-label="Permalink to “Workload inventory”">​</a></h3><p>“Inputs per sample” is the configured number of items or requests a workload processes. For example, <code>string-join</code> joins 25,000 parts 64 times, so its count is 1,600,000. Different workloads count different kinds of input, so compare timings for the same workload rather than comparing counts across rows. The inventory is generated from the benchmark registry and API workload definition.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Workload</th><th>Inputs per sample</th><th>What it represents</th></tr></thead><tbody><tr><td>Synthetic</td><td><code>numeric</code></td><td>1,000,000</td><td>Numeric arithmetic baseline</td></tr><tr><td>Synthetic</td><td><code>objects</code></td><td>50,000</td><td>Object allocation and traversal</td></tr><tr><td>Synthetic</td><td><code>strings</code></td><td>25,000</td><td>String construction and joining</td></tr><tr><td>Synthetic</td><td><code>string-construction</code></td><td>25,000</td><td>String part construction</td></tr><tr><td>Synthetic</td><td><code>string-join</code></td><td>1,600,000</td><td>Batched dense ASCII array joining</td></tr><tr><td>Synthetic</td><td><code>string-radix-integer</code></td><td>25,000</td><td>Integer radix formatting</td></tr><tr><td>Synthetic</td><td><code>string-join-unicode</code></td><td>7</td><td>Unicode join correctness and code-unit behavior</td></tr><tr><td>Synthetic</td><td><code>string-repeat-ascii</code></td><td>4,000</td><td>Repeated ASCII string construction</td></tr><tr><td>Synthetic</td><td><code>string-pad-ascii</code></td><td>8,000</td><td>ASCII string padding at both ends</td></tr><tr><td>Synthetic</td><td><code>array-to-locale-string-ascii</code></td><td>32,000</td><td>Locale string conversion for ASCII array elements</td></tr><tr><td>Synthetic</td><td><code>string-case-ascii</code></td><td>16,000</td><td>ASCII string case conversion</td></tr><tr><td>Synthetic</td><td><code>typed-array-join-ascii</code></td><td>128,000</td><td>ASCII typed array joining</td></tr><tr><td>Synthetic</td><td><code>typed-array-locale-ascii</code></td><td>64,000</td><td>ASCII typed array locale conversion</td></tr><tr><td>Synthetic</td><td><code>string-from-char-code-ascii</code></td><td>8,000</td><td>ASCII multi-argument character code conversion</td></tr><tr><td>Synthetic</td><td><code>string-replace-ascii</code></td><td>16,000</td><td>ASCII string replace and replaceAll</td></tr><tr><td>Synthetic</td><td><code>config-validation</code></td><td>1,000</td><td>Configuration parsing and validation</td></tr><tr><td>Synthetic</td><td><code>command-routing</code></td><td>4,000</td><td>Command tokenization, alias resolution and route-map lookup</td></tr><tr><td>Synthetic</td><td><code>command-tokenization</code></td><td>4,000</td><td>Command tokenization</td></tr><tr><td>Synthetic</td><td><code>command-route-lookup</code></td><td>4,000</td><td>Command alias and route-map lookup</td></tr><tr><td>Synthetic</td><td><code>permission-resolution</code></td><td>12,000</td><td>Permission inheritance and context lookup</td></tr><tr><td>Synthetic</td><td><code>player-directory</code></td><td>18,000</td><td>Player and home lookups</td></tr><tr><td>Synthetic</td><td><code>event-cache</code></td><td>20,000</td><td>Lifecycle cache updates</td></tr><tr><td>Synthetic</td><td><code>chat-formatting</code></td><td>3,000</td><td>Chat template formatting and filtering</td></tr><tr><td>Synthetic</td><td><code>scoreboard-rendering</code></td><td>12,000</td><td>Scoreboard text rendering</td></tr><tr><td>Synthetic</td><td><code>region-protection</code></td><td>20,000</td><td>Region containment and access checks</td></tr><tr><td>Synthetic</td><td><code>world-edit-plan</code></td><td>55,296</td><td>Block-edit plan generation</td></tr><tr><td>Synthetic</td><td><code>economy-transfers</code></td><td>12,000</td><td>Balance transfer processing</td></tr><tr><td>Synthetic</td><td><code>inventory-stacking</code></td><td>2,500</td><td>Inventory stack allocation</td></tr><tr><td>Synthetic</td><td><code>cooldown-rate-limit</code></td><td>20,000</td><td>Cooldown and rate-limit checks</td></tr><tr><td>Synthetic</td><td><code>tick-scheduler</code></td><td>6,000</td><td>Scheduled task processing</td></tr><tr><td>Synthetic</td><td><code>audit-history</code></td><td>13,000</td><td>Audit history filtering</td></tr><tr><td>Synthetic</td><td><code>player-state-json</code></td><td>1,200</td><td>Player-state JSON round trip</td></tr><tr><td>Synthetic</td><td><code>custom-payload</code></td><td>16,384</td><td>Custom payload encoding</td></tr><tr><td>Real API</td><td><code>pumpkin-api</code></td><td>10,000</td><td>Pumpkin server.getAllPlayers()</td></tr></tbody></table><p>String and command workloads include combined cases and narrower sub-operations. The string cases cover construction, joining, radix formatting, Unicode behavior and ASCII-heavy built-ins. Command routing combines tokenization, alias resolution and lookup; separate rows measure tokenization and lookup.</p><h2 id="reading-the-report" tabindex="-1">Reading the report <a class="header-anchor" href="#reading-the-report" aria-label="Permalink to “Reading the report”">​</a></h2><p>The report shows production component sizes, timings and ratios for each workload, and an arithmetic-mean summary.</p><ul><li><strong>Component sizes</strong> are final production component byte counts. Size differences use QuickJS as the baseline: negative means smaller than QuickJS, positive means larger.</li><li><strong>Per-workload timings</strong> show each engine&#39;s median and sample range in milliseconds. A lower time means that engine finished that workload sooner in that run.</li><li><strong>QuickJS/engine</strong> is the QuickJS median divided by that Static Hermes configuration&#39;s median. A ratio above 1 means Hermes was lower; below 1 means QuickJS was lower. A ratio shown as 1.00x can be a rounded tie, especially for workloads close to the timer’s one-millisecond resolution.</li><li><strong>Average benchmark median</strong> is the arithmetic mean of the per-workload medians. It gives every workload equal weight, even though their input counts and work differ. Use it as a compact report statistic, not as a score for plugin or server performance.</li></ul><p>The integration test has no timing thresholds. Timing results are diagnostic evidence, while checksum, API behavior, and component-size checks provide pass/fail assertions.</p><h2 id="example-ci-result" tabindex="-1">Example CI result <a class="header-anchor" href="#example-ci-result" aria-label="Permalink to “Example CI result”">​</a></h2><p>For a concrete example, see the <a href="https://github.com/filiphsps/pumpkin-plugins/actions/runs/38254750702/job/114834399434?pr=99" target="_blank" rel="noreferrer">engine-comparison job from PR 99</a>. It checked out merge commit <code>2a4cfa19157cfabed67f41de16b199c3fc1c0775</code> on a GitHub-hosted Ubuntu 26.04 runner. Treat it as evidence for that merge candidate and runner; it says nothing about master or other revisions. The log does not identify the runner&#39;s CPU model. This older run predates the GC and parser axes in today&#39;s matrix: it compares QuickJS with full and lean Hermes, both using Hades GC. It also predates the repeated join and radix/Unicode workloads, so its <code>string-join</code> row measures a single join and cannot be compared directly with the current workload.</p><h3 id="component-sizes-in-that-run" tabindex="-1">Component sizes in that run <a class="header-anchor" href="#component-sizes-in-that-run" aria-label="Permalink to “Component sizes in that run”">​</a></h3><table tabindex="0"><thead><tr><th>Engine</th><th style="text-align:right;">Component size</th><th style="text-align:right;">Difference from QuickJS</th></tr></thead><tbody><tr><td>QuickJS</td><td style="text-align:right;">5,081,200 bytes</td><td style="text-align:right;">Baseline</td></tr><tr><td>Static Hermes full</td><td style="text-align:right;">3,643,322 bytes</td><td style="text-align:right;">−1,437,878 bytes (−28.30%)</td></tr><tr><td>Static Hermes lean</td><td style="text-align:right;">2,130,174 bytes</td><td style="text-align:right;">−2,951,026 bytes (−58.08%)</td></tr></tbody></table><p>The QuickJS component was 161,680 bytes below the 5 MiB limit. Lean was 1,513,148 bytes smaller than full in this build. These are sizes for the benchmark plugin and build configuration, not fixed sizes for arbitrary plugins.</p><h3 id="per-workload-results-in-that-run" tabindex="-1">Per-workload results in that run <a class="header-anchor" href="#per-workload-results-in-that-run" aria-label="Permalink to “Per-workload results in that run”">​</a></h3><p>Times are median milliseconds, with minimum–maximum samples in parentheses. The final columns show the QuickJS-to-Hermes ratios defined above.</p><table tabindex="0"><thead><tr><th>Workload</th><th style="text-align:right;">Inputs per sample</th><th style="text-align:right;">QuickJS ms</th><th style="text-align:right;">Full ms</th><th style="text-align:right;">Lean ms</th><th style="text-align:right;">QuickJS/full</th><th style="text-align:right;">QuickJS/lean</th></tr></thead><tbody><tr><td><code>numeric</code></td><td style="text-align:right;">1,000,000</td><td style="text-align:right;">114 (113–114)</td><td style="text-align:right;">72 (71–72)</td><td style="text-align:right;">77 (77–91)</td><td style="text-align:right;">1.58x</td><td style="text-align:right;">1.48x</td></tr><tr><td><code>objects</code></td><td style="text-align:right;">50,000</td><td style="text-align:right;">15 (15–16)</td><td style="text-align:right;">12 (8–43)</td><td style="text-align:right;">13 (9–44)</td><td style="text-align:right;">1.25x</td><td style="text-align:right;">1.15x</td></tr><tr><td><code>strings</code></td><td style="text-align:right;">25,000</td><td style="text-align:right;">8 (8–9)</td><td style="text-align:right;">22 (21–23)</td><td style="text-align:right;">23 (22–28)</td><td style="text-align:right;">0.36x</td><td style="text-align:right;">0.35x</td></tr><tr><td><code>string-construction</code></td><td style="text-align:right;">25,000</td><td style="text-align:right;">8 (8–10)</td><td style="text-align:right;">19 (15–23)</td><td style="text-align:right;">22 (15–26)</td><td style="text-align:right;">0.42x</td><td style="text-align:right;">0.36x</td></tr><tr><td><code>string-join</code></td><td style="text-align:right;">25,000</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1.00x</td><td style="text-align:right;">1.00x</td></tr><tr><td><code>config-validation</code></td><td style="text-align:right;">1,000</td><td style="text-align:right;">8 (8–9)</td><td style="text-align:right;">10 (10–12)</td><td style="text-align:right;">11 (11–14)</td><td style="text-align:right;">0.80x</td><td style="text-align:right;">0.73x</td></tr><tr><td><code>command-routing</code></td><td style="text-align:right;">4,000</td><td style="text-align:right;">45 (45–46)</td><td style="text-align:right;">99 (94–100)</td><td style="text-align:right;">102 (98–104)</td><td style="text-align:right;">0.45x</td><td style="text-align:right;">0.44x</td></tr><tr><td><code>command-tokenization</code></td><td style="text-align:right;">4,000</td><td style="text-align:right;">38 (38–39)</td><td style="text-align:right;">91 (90–94)</td><td style="text-align:right;">93 (92–99)</td><td style="text-align:right;">0.42x</td><td style="text-align:right;">0.41x</td></tr><tr><td><code>command-route-lookup</code></td><td style="text-align:right;">4,000</td><td style="text-align:right;">1 (1–2)</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1 (1–1)</td><td style="text-align:right;">1.00x</td><td style="text-align:right;">1.00x</td></tr><tr><td><code>permission-resolution</code></td><td style="text-align:right;">12,000</td><td style="text-align:right;">22 (21–22)</td><td style="text-align:right;">30 (27–31)</td><td style="text-align:right;">31 (27–31)</td><td style="text-align:right;">0.73x</td><td style="text-align:right;">0.71x</td></tr><tr><td><code>player-directory</code></td><td style="text-align:right;">18,000</td><td style="text-align:right;">17 (17–18)</td><td style="text-align:right;">28 (27–33)</td><td style="text-align:right;">31 (29–35)</td><td style="text-align:right;">0.61x</td><td style="text-align:right;">0.55x</td></tr><tr><td><code>event-cache</code></td><td style="text-align:right;">20,000</td><td style="text-align:right;">29 (28–30)</td><td style="text-align:right;">53 (49–55)</td><td style="text-align:right;">56 (53–59)</td><td style="text-align:right;">0.55x</td><td style="text-align:right;">0.52x</td></tr><tr><td><code>chat-formatting</code></td><td style="text-align:right;">3,000</td><td style="text-align:right;">35 (34–36)</td><td style="text-align:right;">52 (48–53)</td><td style="text-align:right;">53 (50–53)</td><td style="text-align:right;">0.67x</td><td style="text-align:right;">0.66x</td></tr><tr><td><code>scoreboard-rendering</code></td><td style="text-align:right;">12,000</td><td style="text-align:right;">103 (100–111)</td><td style="text-align:right;">154 (152–161)</td><td style="text-align:right;">164 (160–170)</td><td style="text-align:right;">0.67x</td><td style="text-align:right;">0.63x</td></tr><tr><td><code>region-protection</code></td><td style="text-align:right;">20,000</td><td style="text-align:right;">21 (20–21)</td><td style="text-align:right;">28 (28–29)</td><td style="text-align:right;">28 (28–29)</td><td style="text-align:right;">0.75x</td><td style="text-align:right;">0.75x</td></tr><tr><td><code>world-edit-plan</code></td><td style="text-align:right;">55,296</td><td style="text-align:right;">23 (23–24)</td><td style="text-align:right;">11 (11–12)</td><td style="text-align:right;">12 (11–12)</td><td style="text-align:right;">2.09x</td><td style="text-align:right;">1.92x</td></tr><tr><td><code>economy-transfers</code></td><td style="text-align:right;">12,000</td><td style="text-align:right;">145 (143–153)</td><td style="text-align:right;">14 (9–19)</td><td style="text-align:right;">16 (10–20)</td><td style="text-align:right;">10.36x</td><td style="text-align:right;">9.06x</td></tr><tr><td><code>inventory-stacking</code></td><td style="text-align:right;">2,500</td><td style="text-align:right;">11 (10–11)</td><td style="text-align:right;">5 (4–6)</td><td style="text-align:right;">5 (4–6)</td><td style="text-align:right;">2.20x</td><td style="text-align:right;">2.20x</td></tr><tr><td><code>cooldown-rate-limit</code></td><td style="text-align:right;">20,000</td><td style="text-align:right;">12 (11–12)</td><td style="text-align:right;">16 (15–17)</td><td style="text-align:right;">17 (16–21)</td><td style="text-align:right;">0.75x</td><td style="text-align:right;">0.71x</td></tr><tr><td><code>tick-scheduler</code></td><td style="text-align:right;">6,000</td><td style="text-align:right;">10 (10–11)</td><td style="text-align:right;">8 (5–9)</td><td style="text-align:right;">9 (5–10)</td><td style="text-align:right;">1.25x</td><td style="text-align:right;">1.11x</td></tr><tr><td><code>audit-history</code></td><td style="text-align:right;">13,000</td><td style="text-align:right;">73 (72–75)</td><td style="text-align:right;">9 (5–10)</td><td style="text-align:right;">9 (5–10)</td><td style="text-align:right;">8.11x</td><td style="text-align:right;">8.11x</td></tr><tr><td><code>player-state-json</code></td><td style="text-align:right;">1,200</td><td style="text-align:right;">17 (17–19)</td><td style="text-align:right;">12 (7–13)</td><td style="text-align:right;">12 (8–14)</td><td style="text-align:right;">1.42x</td><td style="text-align:right;">1.42x</td></tr><tr><td><code>custom-payload</code></td><td style="text-align:right;">16,384</td><td style="text-align:right;">4 (3–4)</td><td style="text-align:right;">2 (2–2)</td><td style="text-align:right;">2 (2–2)</td><td style="text-align:right;">2.00x</td><td style="text-align:right;">2.00x</td></tr><tr><td><code>pumpkin-api</code></td><td style="text-align:right;">10,000</td><td style="text-align:right;">11 (11–12)</td><td style="text-align:right;">39 (38–44)</td><td style="text-align:right;">39 (39–44)</td><td style="text-align:right;">0.28x</td><td style="text-align:right;">0.28x</td></tr></tbody></table><p>In this run, full Hermes had a lower median than QuickJS on 9 rows, QuickJS had a lower median on 13, and 2 displayed as ties. Lean had the same count split. Those ties are at the reported precision; they do not establish equal execution cost. The large spread on some rows, such as object allocation, is also a reminder that a five-sample range can expose variability rather than eliminate it.</p><h2 id="what-the-results-suggest—and-what-they-do-not-prove" tabindex="-1">What the results suggest—and what they do not prove <a class="header-anchor" href="#what-the-results-suggest—and-what-they-do-not-prove" aria-label="Permalink to “What the results suggest—and what they do not prove”">​</a></h2><p>The example shows differences by workload, not one engine winning across the board. QuickJS was faster in the command-tokenization and string-construction fixtures. Full and lean Hermes were faster in the numeric baseline and several state-processing fixtures, especially <code>economy-transfers</code> and <code>audit-history</code>. QuickJS was faster on the real API row, which repeatedly calls <code>getAllPlayers()</code> and gets an empty list. None of these results predicts a plugin&#39;s end-to-end performance on its own.</p><p>Several things could explain the pattern, but this benchmark doesn&#39;t profile them:</p><ul><li><strong>Bytecode and interpreter behavior.</strong> Both runtimes use their own JavaScript representations and virtual machines in this WASI setup. Instruction dispatch, optimization choices, and runtime implementation could affect arithmetic and control-heavy loops. There is no instruction-level profile to tell us which, if any, caused a timing difference.</li><li><strong>Built-ins and strings.</strong> String construction, joining, JSON, maps, and object operations use engine-specific implementations. In the example run, the separate join row takes about one millisecond, while construction and combined string work take longer and favor QuickJS. That suggests construction may account for more of the measured difference, but the workloads don&#39;t isolate every internal operation.</li><li><strong>Allocation and garbage collection.</strong> Object-heavy or state-heavy work may respond to object layout, allocation strategy, or collection timing. The report has no heap, allocation, or GC counters, so these are possibilities, not findings.</li><li><strong>The Wasm host boundary.</strong> The API row includes real Pumpkin/WIT/JSI call plumbing and the JavaScript call loop. Since the server has no players, it doesn&#39;t measure converting or traversing a large player list. The result can&#39;t separate host-call overhead from the rest of that call path.</li><li><strong>Workload shape.</strong> A fixture might favor an engine&#39;s built-ins or implementation details without matching a production plugin&#39;s data sizes, branches, object lifetimes, API calls, or tick cadence.</li></ul><p>For an engine or plugin decision, benchmark the plugin&#39;s actual hot path with realistic data and production build settings. Use a profiler or targeted counters before attributing a timing difference to a particular cause.</p><h2 id="limits-and-interpretation-rules" tabindex="-1">Limits and interpretation rules <a class="header-anchor" href="#limits-and-interpretation-rules" aria-label="Permalink to “Limits and interpretation rules”">​</a></h2><ul><li>The table is one run of one PR merge candidate. Hardware, host load, Wasmtime and Pumpkin versions, toolchain pins, and source changes can all affect results. Use the linked job for provenance, and compare the same revisions and environments.</li><li>The job log identifies a GitHub-hosted Ubuntu 26.04 runner but not its CPU model. Do not infer a CPU from the operating-system image.</li><li>Five samples measured in whole milliseconds can reveal large differences, but they can&#39;t reliably resolve small ones. A sample may take zero milliseconds; the report can&#39;t calculate a ratio when its denominator median is zero.</li><li>Locally, the comparison runs configurations serially in a fixed order. CI gives each one a matrix job, but runner differences can affect timings, and a job doesn&#39;t repeat on multiple runners.</li><li>Input counts differ by design. A million arithmetic iterations and 1,000 config validations are not equivalent units. Do not average or compare rows as if they were normalized operations.</li><li>The arithmetic mean weights every workload median equally. A single slower row can move it substantially, and changing the workload set changes its meaning.</li><li>The real API case is narrow: it measures one API method with an empty result, not all Pumpkin calls or guest-to-host conversion costs.</li><li>Component size is the benchmark plugin&#39;s final component size. Plugin imports, bundled dependencies, API usage, and build profile change the result.</li></ul><h2 id="for-runtime-and-ci-contributors" tabindex="-1">For runtime and CI contributors <a class="header-anchor" href="#for-runtime-and-ci-contributors" aria-label="Permalink to “For runtime and CI contributors”">​</a></h2><p>If you change the benchmark or its CI workflow, keep these guarantees in place:</p><ul><li>Use identical workload code and input counts across engine builds, and preserve the deterministic checksum checks.</li><li>Keep labels clear about provenance: guest-side synthetic fixture or real Pumpkin API.</li><li>Keep API behavior assertions separate from timed synthetic algorithms unless you&#39;re explicitly measuring the API path.</li><li>Remember that adding a workload or changing fixture inputs changes what the average means.</li><li>Include the runner image and source revision with any published comparison. Include CPU details only when the runner exposes them.</li><li>Use the runtime guide for the pinned Hermes/WASI toolchain and build configuration; use the test harness guide for server selection and startup behavior.</li></ul><p>The comparison is maintained in <a href="../benchmarks/engine-comparison/test/engine-comparison.test.ts">engine-comparison.test.ts</a>, <a href="../benchmarks/engine-comparison/test/engine-variants.ts">engine-variants.ts</a>, <a href="../benchmarks/engine-comparison/src/benchmark-workloads.ts">benchmark-workloads.ts</a>, <a href="../benchmarks/engine-comparison/src/benchmark-plugin.ts">benchmark-plugin.ts</a>, and the <a href="../.github/workflows/engine-comparison.yml">comparison workflow</a>. See <a href="/pumpkin-plugins/guides/testing">Testing</a> for the real-server harness.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to “Sources”">​</a></h2><ul><li><a href="https://bellard.org/quickjs/quickjs.html" target="_blank" rel="noreferrer">QuickJS official documentation</a>: engine overview, interpreter/compiler, bytecode, and memory handling.</li><li><a href="https://github.com/facebook/hermes/blob/main/doc/BuildingAndRunning.md" target="_blank" rel="noreferrer">Hermes official build and execution guide</a>: Hermes bytecode compiler and execution modes.</li><li><a href="/pumpkin-plugins/guides/building">Pumpkin plugin build guide</a> and <a href="./../tools/static-hermes-runtime/README">Static Hermes Runtime guide</a>: this repository’s component build, engine profiles, and WASI configuration.</li><li><a href="https://github.com/filiphsps/pumpkin-plugins/actions/runs/38254750702/job/114834399434?pr=99" target="_blank" rel="noreferrer">PR 99 engine-comparison job</a>: source revision, runner context, component sizes, and workload output for the example above.</li></ul>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};